import React, { useId } from "react"
import { motion, useTime, useTransform } from "motion/react"
import { cn } from "@/lib/utils"

export interface SquigglyTextProps {
  /** Texto (ou qualquer node) a envolver com o efeito squiggly. */
  children: React.ReactNode
  className?: string
  style?: React.CSSProperties
  /** Quantidade de filtros SVG gerados (cada um com seed diferente).
   *  O efeito cicla entre eles a cada `stepDuration` ms. @default 5 */
  steps?: number
  /** Duração em ms de cada passo do ciclo. @default 80 */
  stepDuration?: number
  /** Intensidade do displacement. Número único ou tupla alternada por step.
   *  @default [6, 8] */
  scale?: number | [number, number]
  /** Frequência base do ruído (turbulência). @default 0.02 */
  baseFrequency?: number
  /** Octaves do `feTurbulence`. @default 3 */
  numOctaves?: number
  /** Elemento raiz. "span" é inline; "div" quebra pra bloco.
   *  @default "span" */
  as?: "span" | "div"
}

export function SquigglyText({
  children,
  steps = 5,
  stepDuration = 80,
  scale = [6, 8],
  baseFrequency = 0.02,
  numOctaves = 3,
  as = "span",
  className,
  style,
}: SquigglyTextProps) {
  const reactId = useId()
  // useId pode gerar ":" / "_" inválidos em url(#…)
  const safeId = reactId.replace(/[:_]/g, "")
  const filterId = React.useCallback(
    (i: number) => `squiggly-${safeId}-${i}`,
    [safeId],
  )

  const filters = React.useMemo(
    () => Array.from({ length: steps }, (_, i) => `url(#${filterId(i)})`),
    [steps, filterId],
  )

  const time = useTime()
  const filter = useTransform(
    time,
    (t) => filters[Math.floor(t / stepDuration) % filters.length],
  )

  const scaleAt = (i: number) =>
    Array.isArray(scale) ? scale[i % scale.length] : scale

  const Wrapper = as === "div" ? motion.div : motion.span

  return (
    <Wrapper
      style={{ filter, ...style }}
      className={cn("inline-block", className)}
      data-slot="squiggly-text"
    >
      <svg
        aria-hidden
        className="pointer-events-none absolute h-0 w-0 overflow-hidden"
        xmlns="http://www.w3.org/2000/svg"
      >
        <defs>
          {Array.from({ length: steps }).map((_, i) => (
            <filter id={filterId(i)} key={i}>
              <feTurbulence
                baseFrequency={baseFrequency}
                numOctaves={numOctaves}
                result="noise"
                seed={i}
              />
              <feDisplacementMap
                in="SourceGraphic"
                in2="noise"
                scale={scaleAt(i)}
              />
            </filter>
          ))}
        </defs>
      </svg>
      {children}
    </Wrapper>
  )
}
